  "description": "Add a single item to the user's Kroger cart and track it locally.

If the user doesn't specifically indicate a preference for pickup or delivery,
you should ask them which modality they prefer before calling this tool.

Args:
    product_id: The product ID or UPC to add to cart
    quantity: Quantity to add (default: 1)
    modality: Fulfillment method - PICKUP or DELIVERY

Returns:
    Dictionary confirming the item was added to cart",
  "inputSchema": {
    "type": "object",
    "properties": {
      "product_id": {
        "type": "string"
      },
      "quantity": {
        "type": "integer"
      },
      "modality": {
        "type": "string"
      }
    },
    "required": [
      "product_id"
    ]
  },
  "handler": "async def add_items_to_cart(
        product_id: str,
        quantity: int = 1,
        modality: str = "PICKUP",
        ctx: Context = None
    ) -> Dict[str, Any]:
        """
        Add a single item to the user's Kroger cart and track it locally.

        If the user doesn't specifically indicate a preference for pickup or delivery,
        you should ask them which modality they prefer before calling this tool.

        Args:
            product_id: The product ID or UPC to add to cart
            quantity: Quantity to add (default: 1)
            modality: Fulfillment method - PICKUP or DELIVERY

        Returns:
            Dictionary confirming the item was added to cart
        """
        try:
            if ctx:
                await ctx.info(f"Adding {quantity}x {product_id} to cart with {modality} modality")

            # Get authenticated client
            client = get_authenticated_client()

            # Format the item for the API
            cart_item = {
                "upc": product_id,
                "quantity": quantity,
                "modality": modality
            }

            if ctx:
                await ctx.info(f"Calling Kroger API to add item: {cart_item}")

            # Add the item to the actual Kroger cart
            # Note: add_to_cart returns None on success, raises exception on failure
            client.cart.add_to_cart([cart_item])

            if ctx:
                await ctx.info("Successfully added item to Kroger cart")

            # Add to local cart tracking
            _add_item_to_local_cart(product_id, quantity, modality)

            if ctx:
                await ctx.info("Item added to local cart tracking")

            return {
                "success": True,
                "message": f"Successfully added {quantity}x {product_id} to cart",
                "product_id": product_id,
                "quantity": quantity,
                "modality": modality,
                "timestamp": datetime.now().isoformat()
            }

        except Exception as e:
            if ctx:
                await ctx.error(f"Failed to add item to cart: {str(e)}")

            # Provide helpful error message for authentication issues
            error_message = str(e)
            if "401" in error_message or "Unauthorized" in error_message:
                return {
                    "success": False,
                    "error": "Authentication failed. Please run force_reauthenticate and try again.",
                    "details": error_message
                }
            elif "400" in error_message or "Bad Request" in error_message:
                return {
                    "success": False,
                    "error": f"Invalid request. Please check the product ID and try again.",
                    "details": error_message
                }
            else:
                return {
                    "success": False,
                    "error": f"Failed to add item to cart: {error_message}",
                    "product_id": product_id,
                    "quantity": quantity,
                    "modality": modality
                }"
}

{
  "name": "complete_authentication",
  "description": "Complete the OAuth flow using the redirect URL from Kroger.

After opening the auth URL in your browser and authorizing the app,
you'll be redirected to a callback URL. Copy that entire URL and
pass it to this tool to complete the authentication process.

Args:
    redirect_url: The full URL from your browser after authorization

Returns:
    Dictionary indicating authentication status",
  "inputSchema": {
    "type": "object",
    "properties": {
      "redirect_url": {
        "type": "string"
      }
    },
    "required": [
      "redirect_url"
    ]
  },
  "handler": "async def complete_authentication(redirect_url: str, ctx: Context = None) -> Dict[str, Any]:
        """
        Complete the OAuth flow using the redirect URL from Kroger.

        After opening the auth URL in your browser and authorizing the app,
        you'll be redirected to a callback URL. Copy that entire URL and
        pass it to this tool to complete the authentication process.

        Args:
            redirect_url: The full URL from your browser after authorization

        Returns:
            Dictionary indicating authentication status
        """
        global _pkce_params, _auth_state

        if not _pkce_params or not _auth_state:
            if ctx:
                await ctx.error("Authentication flow not started")
            return {
                "error": True,
                "message": "Authentication flow not started. Please use start_authentication first."
            }

        try:
            # Parse the redirect URL
            parsed_url = urlparse(redirect_url)
            query_params = parse_qs(parsed_url.query)

            # Extract code and state
            if 'code' not in query_params:
                if ctx:
                    await ctx.error("Authorization code not found in redirect URL")
                return {
                    "error": True,
                    "message": "Authorization code not found in redirect URL. Please check the URL and try again."
                }

            auth_code = query_params['code'][0]
            received_state = query_params.get('state', [None])[0]

            # Verify state parameter to prevent CSRF attacks
            if received_state != _auth_state:
                if ctx:
                    await ctx.error(f"State mismatch: expected {_auth_state}, got {received_state}")
                return {
                    "error": True,
                    "message": "State parameter mismatch. This could indicate a CSRF attack. Please try authenticating again."
                }

            # Get client credentials
            client_id = os.environ.get("KROGER_CLIENT_ID")
            client_secret = os.environ.get("KROGER_CLIENT_SECRET")
            redirect_uri = os.environ.get("KROGER_REDIRECT_URI", "http://localhost:8000/callback")

            if not client_id or not client_secret:
                if ctx:
                    await ctx.error("Missing Kroger API credentials")
                return {
                    "error": True,
                    "message": "Missing Kroger API credentials. Please set KROGER_CLIENT_ID and KROGER_CLIENT_SECRET."
                }

            # Initialize Kroger API client
            kroger = KrogerAPI()

            # Exchange the authorization code for tokens with the code verifier
            if ctx:
                await ctx.info(f"Exchanging authorization code for tokens with code_verifier")

            # Use the code_verifier from the PKCE parameters
            token_info = kroger.authorization.get_token_with_authorization_code(
                auth_code,
                code_verifier=_pkce_params["code_verifier"]
            )

            # Clear PKCE parameters and state after successful exchange
            _pkce_params = None
            _auth_state = None

            if ctx:
                await ctx.info(f"Authentication successful!")

            # Return success response
            return {
                "success": True,
                "message": "Authentication successful! You can now use Kroger API tools that require authentication.",
                "token_info": {
                    "expires_in": token_info.get("expires_in"),
                    "token_type": token_info.get("token_type"),
                    "scope": token_info.get("scope"),
                    "has_refresh_token": "refresh_token" in token_info
                }
            }

        except Exception as e:
            error_message = str(e)

            if ctx:
                await ctx.error(f"Authentication error: {error_message}")

            return {
                "error": True,
                "message": f"Authentication failed: {error_message}"
            }"
}

