  "name": "research_topic",
  "description": "End-to-end deterministic research workflow. One tool, two modes:

  topic  - open-ended search + fetch + extract
  entity - unified cross-source profile of a named entity

Both modes auto-attach per-result quality scores and an aggregate
confidence signal so callers can calibrate trust.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "topic": {
        "type": "string"
      },
      "mode": {
        "type": "string"
      },
      "sources": {
        "type": "string"
      },
      "max_sources": {
        "type": "string"
      },
      "include_analysis": {
        "type": "string"
      }
    },
    "required": [
      "topic"
    ]
  },
  "handler": "async def research_topic(
        topic: Annotated[
            str,
            Field(
                description=(
                    "Subject of the research. A topic or question in "
                    "`topic` mode (e.g. 'transformer attention'); an "
                    "entity name in `entity` mode (e.g. 'OpenAI', "
                    "'FastMCP', 'Linus Torvalds')."
                ),
                min_length=2,
                max_length=300,
            ),
        ],
        mode: Annotated[
            ResearchMode,
            Field(
                description=(
                    "topic  - search + fetch + extract findings from top sources.\n"
                    "entity - profile a named entity by fanning out across "
                    "web, news, GitHub, social, and academic sources in "
                    "parallel. Returns a unified multi-section report."
                ),
                default="topic",
            ),
        ] = "topic",
        sources: Annotated[
            Optional[List[str]],
            Field(
                description=(
                    "topic mode only: override the search step with these "
                    "specific URLs. Ignored in entity mode."
                ),
                default=None,
            ),
        ] = None,
        max_sources: Annotated[
            int,
            Field(
                description="Upper bound on sources per section.",
                ge=1,
                le=20,
                default=5,
            ),
        ] = 5,
        include_analysis: Annotated[
            bool,
            Field(
                description=(
                    "topic mode only: run key-findings extraction on " "retrieved content."
                ),
                default=True,
            ),
        ] = True,
        ctx: Optional[Context] = None,
    ) -> str:
        """
        End-to-end deterministic research workflow. One tool, two modes:

          topic  - open-ended search + fetch + extract
          entity - unified cross-source profile of a named entity

        Both modes auto-attach per-result quality scores and an aggregate
        confidence signal so callers can calibrate trust.
        """
        try:
            if mode == "entity":
                return await _run_entity_mode(topic, max_sources=max_sources, ctx=ctx)
            return await _run_topic_mode(
                topic,
                sources=sources,
                max_sources=max_sources,
                include_analysis=include_analysis,
            )
        except Exception as e:
            logger.error(f"Research topic failed: {e}")
            return format_research_analysis_markdown(
                {"topic": topic, "status": "error", "error": str(e)},
                "Topic Research",
            )"
}

{
  "name": "get_dataservice_info",
  "description": "Get detailed metadata about a specific third-party API (dataservice).

Returns title, description, organization, base_api_url,
machine_documentation_url (OpenAPI/Swagger spec), license, and dates.

To use a third-party API: (1) get its info here, (2) fetch the OpenAPI spec
via get_dataservice_openapi_spec, (3) call base_api_url per spec.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "dataservice_id": {
        "type": "string"
      }
    },
    "required": [
      "dataservice_id"
    ]
  },
  "handler": "async def get_dataservice_info(dataservice_id: str) -> str:
        """
        Get detailed metadata about a specific third-party API (dataservice).

        Returns title, description, organization, base_api_url,
        machine_documentation_url (OpenAPI/Swagger spec), license, and dates.

        To use a third-party API: (1) get its info here, (2) fetch the OpenAPI spec
        via get_dataservice_openapi_spec, (3) call base_api_url per spec.
        """
        try:
            data = await datagouv_api_client.get_dataservice_details(dataservice_id)

            content_parts = [
                f"Third-party API information: {data.get('title', 'Unknown')}",
                "",
            ]

            if data.get("id"):
                content_parts.append(f"ID: {data.get('id')}")
            content_parts.append(
                f"URL: {env_config.get_base_url('site')}dataservices/{data.get('id', '')}/"
            )

            if data.get("description"):
                content_parts.append("")
                desc = data.get("description", "")[:500]
                content_parts.append(f"Description: {desc}...")

            # Catalog resource fields for this third-party API (dataservice)
            content_parts.append("")
            if data.get("base_api_url"):
                content_parts.append(f"Base API URL: {data.get('base_api_url')}")
            if data.get("machine_documentation_url"):
                content_parts.append(
                    f"OpenAPI/Swagger spec: {data.get('machine_documentation_url')}"
                )

            if data.get("organization"):
                org = data.get("organization", {})
                if isinstance(org, dict):
                    content_parts.append("")
                    content_parts.append(f"Organization: {org.get('name', 'Unknown')}")
                    if org.get("id"):
                        content_parts.append(f"  Organization ID: {org.get('id')}")

            tags: list[str] = data.get("tags") or []
            if tags:
                content_parts.append("")
                content_parts.append(f"Tags: {', '.join(tags[:10])}")

            # Dates
            if data.get("created_at"):
                content_parts.append("")
                content_parts.append(f"Created: {data.get('created_at')}")
            if data.get("last_update"):
                content_parts.append(f"Last updated: {data.get('last_update')}")

            # License
            if data.get("license"):
                content_parts.append("")
                content_parts.append(f"License: {data.get('license')}")

            # Related datasets (API returns a link object, not a list)
            datasets: dict[str, Any] = data.get("datasets", {})
            if isinstance(datasets, dict) and datasets.get("total"):
                content_parts.append("")
                content_parts.append(f"Related datasets: {datasets['total']}")

            return "\n".join(content_parts)

        except httpx.HTTPStatusError as e:
