{
  "name": "persist_artifact",
  "description": "Upload a file previously created by run_code to a presigned URL. The file path must be relative to the output/ directory of the current session, for example 'reports/report.pdf'. The client must include the same mcp-session-id header used for run_code so the tool can locate the correct session workspace.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "relative_path": {
        "type": "string"
      },
      "presigned_url": {
        "type": "string"
      }
    },
    "required": [
      "relative_path",
      "presigned_url"
    ]
  },
  "handler": "async def _persist_artifact(
        relative_path: str,
        presigned_url: str,
        ctx: Context | None = None,
    ) -> dict:  # {uploaded_bytes: int, status: int}
        """Upload *relative_path* to *presigned_url* and return upload stats."""

        # Basic sanitisation
        if Path(relative_path).is_absolute() or ".." in Path(relative_path).parts:
            raise ValueError(
                "relative_path must be inside output/ and cannot contain '..'"
            )

        # Determine session ID
        sid = ctx.session_id
        if not sid and ctx.request_context.request:
            sid = ctx.request_context.request.headers.get("mcp-session-id")
        if not sid:
            raise ValueError("Missing session_id; ensure mcp-session-id header is set.")

        output_dir = TMP_DIR / f"session_{sid}" / "output"
        file_path = output_dir / relative_path
        if not file_path.is_file():
            raise FileNotFoundError("Artifact not found: " + relative_path)

        size = file_path.stat().st_size
        if size > MAX_UPLOAD_BYTES:
            raise ValueError(f"Artifact exceeds size limit ({MAX_UPLOAD_BYTES} bytes)")

        async with aiohttp.ClientSession() as session:
            with file_path.open("rb") as fh:
                resp = await session.put(presigned_url, data=fh)
                status = resp.status
                await resp.release()
                if status >= 400:
                    raise RuntimeError(f"Upload failed with HTTP {status}")

        return {"uploaded_bytes": size, "status": status}"
}

{
  "name": "get_table_fields",
  "description": "Get all fields/columns in a specific table.

Args:
    table_id: The ID of the table.
    limit: Maximum number of fields to return (default: 20).

Returns:
    Dictionary with field metadata, truncated if necessary.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "table_id": {
        "type": "integer"
      },
      "limit": {
        "type": "integer"
      }
    },
    "required": [
      "table_id"
    ]
  },
  "handler": "async def get_table_fields(table_id: int, ctx: Context, limit: int = 20) -> dict[str, Any]:
    """
    Get all fields/columns in a specific table.

    Args:
        table_id: The ID of the table.
        limit: Maximum number of fields to return (default: 20).

    Returns:
        Dictionary with field metadata, truncated if necessary.
    """
    try:
        await ctx.info(f"Fetching fields for table {table_id}")
        result = await metabase_client.request("GET", f"/table/{table_id}/query_metadata")

        # Apply field limiting
        if limit > 0 and "fields" in result and len(result["fields"]) > limit:
            total_fields = len(result["fields"])
            result["fields"] = result["fields"][:limit]
            result["_truncated"] = True
            result["_total_fields"] = total_fields
            result["_limit_applied"] = limit
            await ctx.info(f"Truncated {total_fields} fields to {limit} fields")
        else:
            await ctx.info(f"Retrieved {len(result.get('fields', []))} fields")

        return result
    except Exception as e:
        error_msg = f"Error getting table fields for table {table_id}: {e}"
        await ctx.error(error_msg)
        raise ToolError(error_msg) from e"
}

{
  "name": "ha_manage_backup",
  "description": "Polymorphic backup tool. See the tool description for the routing matrix.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "scope": {
        "type": "string"
      },
      "action": {
        "type": "string"
      },
      "name": {
        "type": "string"
      },
      "backup_id": {
        "type": "string"
      },
      "restore_database": {
        "type": "string"
      },
      "domain": {
        "type": "string"
      },
      "entity_id": {
        "type": "string"
      },
      "backup_name": {
        "type": "string"
      },
      "older_than_days": {
        "type": "string"
      },
      "limit": {
        "type": "string"
      }
    },
    "required": [
      "scope",
      "action"
    ]
  },
  "handler": "async def ha_manage_backup(
        scope: Annotated[
            Literal["snapshot", "edits"],
            Field(
                description="'snapshot' for full HA tarballs; 'edits' for per-entity auto-backups."
            ),
        ],
        action: Annotated[
            Literal["create", "restore", "list", "view", "diff", "delete"],
            Field(
                description="Operation to perform. Valid (scope, action) combinations are listed in the tool description."
            ),
        ],
        # snapshot scope params
        name: Annotated[
            str | None,
            Field(
                default=None,
                description="(snapshot.create) Tarball name. Auto-generated if not provided.",
            ),
        ] = None,
        backup_id: Annotated[
            str | None,
            Field(
                default=None,
                description="(snapshot.restore) Tarball ID to restore (e.g. 'dd7550ed').",
            ),
        ] = None,
        restore_database: Annotated[
            bool,
            Field(
                default=False,
                description="(snapshot.restore) Include database in the restore. Default false (config-only).",
            ),
        ] = False,
        # edits scope params
        domain: Annotated[
            str | None,
            Field(
                default=None,
                description="(edits.list / edits.delete) Filter auto-backups by domain (e.g. 'automation', 'helper_timer').",
            ),
        ] = None,
        entity_id: Annotated[
            str | None,
            Field(
                default=None,
                description="(edits.list / edits.delete) Filter auto-backups by entity ID.",
            ),
        ] = None,
        backup_name: Annotated[
            str | None,
            Field(
                default=None,
                description=(
                    "(edits.view / edits.restore / edits.delete) Auto-backup filename "
                    "(format '<domain>.<entity_id>.<timestamp>.yaml'). Not a tarball ID."
                ),
            ),
        ] = None,
        older_than_days: Annotated[
            int | None,
            Field(
                default=None,
                ge=0,
                description="(edits.delete) Bulk-delete auto-backups older than this many days.",
            ),
        ] = None,
        limit: Annotated[
            int,
            Field(
                default=200,
                ge=1,
                le=10_000,
                description="(edits.list / snapshot.list) Maximum number of entries to return.",
            ),
        ] = 200,
    ) -> dict[str, Any]:
        """Polymorphic backup tool. See the tool description for the routing matrix."""
        _gate_combo(scope, action)

        if scope == "snapshot":
            if action == "create":
                return await create_backup(client, name)
            if action == "list":
                return await list_backups(client, limit)
            # action == "restore"
            bid = _require("backup_id", backup_id, scope, action)
            return await restore_backup(client, bid, restore_database)

        # scope == "edits"
        settings = get_global_settings()
        mgr = get_backup_manager(client, settings)

        if action == "create":
            # On-demand snapshot for "I'm about to edit this in the HA UI,
            # save the current state first." Drives the same handler path
            # the ``@with_auto_backup`` decorator uses on writes, but goes
            # through ``mgr.maybe_snapshot(force=True)`` which bypasses
            # both the ``enable_auto_backup`` toggle and the per-entity
            # throttle window — the request is explicit, so neither
            # should suppress it.
            dom = _require("domain", domain, scope, action)
            eid = _require("entity_id", entity_id, scope, action)
            if mgr.handler_for(dom) is None:
                raise_tool_error(
                    create_error_response(
                        ErrorCode.VALIDATION_INVALID_PARAMETER,
                        f"No backup handler registered for domain={dom!r}",
                        context={"domain": dom, "entity_id": eid},
                        suggestions=[
                            "Supported domains: " + ", ".join(mgr.supported_domains()),
                        ],
                    )
                )
            path = await mgr.maybe_snapshot(
                dom,
                eid,
                tool_name="ha_manage_backup.edits.create",
                force=True,
            )
            if path is None:
                raise_tool_error(
                    create_error_response(
                        ErrorCode.RESOURCE_NOT_FOUND,
                        f"Could not snapshot {dom}:{eid} — entity not found "
                        + "or fetch returned no config",
                        context={"domain": dom, "entity_id": eid},
                        suggestions=[
                            "Verify the entity exists via the matching "
                            + "ha_config_get_* tool first",
                            "For helpers, pass domain='helper_<helper_type>' "
                            + "(e.g. 'helper_input_boolean')",
                        ],
                    )
                )
            return {
                "success": True,
                "data": {
                    "backup_name": path.name,
                    "domain": dom,
                    "entity_id": eid,
                    "size": path.stat().st_size,
                },
            }

        if action == "list":
            # list_snapshots does sync directory globbing + per-file stat;
            # offload to the executor so it doesn't block the event loop
            # when the backup dir holds many files.
            entries = await asyncio.to_thread(
                mgr.list_snapshots,
                domain=domain,
                entity_id=entity_id,
                limit=limit,
            )
            return {
                "success": True,
                "data": {
                    "backups": entries,
                    "count": len(entries),
                    "backup_dir": str(mgr.backup_dir),
                    "enabled": mgr.enabled,
                    "throttle_minutes": settings.auto_backup_throttle_minutes,
                    "retain_per_entity": settings.auto_backup_retain_per_entity,
                },
            }

        if action == "view":
            bname = _require("backup_name", backup_name, scope, action)
            try:
                data = await asyncio.to_thread(mgr.read_snapshot, bname)
            except FileNotFoundError:
                raise_tool_error(
                    create_error_response(
                        ErrorCode.RESOURCE_NOT_FOUND,
                        f"Backup {bname!r} not found",
                        context={"backup_name": bname},
                    )
                )
            except ValueError as err:
                raise_tool_error(
                    create_error_response(
                        ErrorCode.VALIDATION_INVALID_PARAMETER,
                        str(err),
                        context={"backup_name": bname},
                    )
                )
            return {"success": True, "data": data}

        if action == "diff":
            bname = _require("backup_name", backup_name, scope, action)
            try:
                diff = await mgr.diff_snapshot(bname)
            except FileNotFoundError:
                raise_tool_error(
                    create_error_response(
                        ErrorCode.RESOURCE_NOT_FOUND,
                        f"Backup {bname!r} not found",
                        context={"backup_name": bname},
                    )
                )
            except (ValueError, LookupError) as err:
                raise_tool_error(
                    create_error_response(
                        ErrorCode.VALIDATION_INVALID_PARAMETER,
                        str(err),
                        context={"backup_name": bname},
                    )
                )
            except ToolError:
                raise
            except Exception as err:
                # Fetching the live config for diff goes through the
                # same domain handler ``restore`` uses, so the same
                # HA-side failure modes (4xx/5xx, WS errors, schema
                # drift) apply. Funnel through
                # ``exception_to_structured_error`` so the structured
                # response carries enough context to retry.
                exception_to_structured_error(
                    err,
                    context={"backup_name": bname, "action": "diff"},
                    suggestions=[
                        "Verify the entity referenced by the backup still "
                        + "exists; diff fetches its current config",
                        "Inspect the snapshot YAML via "
                        + "ha_manage_backup(scope='edits', action='view', "
                        + "backup_name=...) to confirm it parses",
                    ],
                )
                return None  # unreachable: exception_to_structured_error always raises
            warnings: list[str] = []
            if diff.get("entity_missing"):
                # ``restore_snapshot`` outcome on a missing entity is
                # domain-dependent: upsert paths (automation, script,
                # dashboard) recreate it, but helper / label / category
                # restores go through ``<domain>/update`` WS commands
                # that expect the entity to exist and would surface a
                # WS error if it does not. Hedge rather than promise
                # one specific outcome.
                warnings.append(
                    "Entity is missing from HA; restore behaviour is "
                    "domain-dependent (upsert paths recreate it; "
                    "update-only paths return an error)"
                )
            if diff.get("truncated"):
                warnings.append(
                    "Patch truncated; entity has more changes than the bounded "
                    "diff captures — view the snapshot for the full state"
                )
            return {
                "success": True,
                "data": diff,
                **({"warnings": warnings} if warnings else {}),
            }

        if action == "restore":
            bname = _require("backup_name", backup_name, scope, action)
            try:
                result = await mgr.restore_snapshot(bname)
            except FileNotFoundError:
                raise_tool_error(
                    create_error_response(
                        ErrorCode.RESOURCE_NOT_FOUND,
                        f"Backup {bname!r} not found",
                        context={"backup_name": bname},
                    )
                )
            except (ValueError, LookupError) as err:
                raise_tool_error(
                    create_error_response(
                        ErrorCode.VALIDATION_INVALID_PARAMETER,
                        str(err),
                        context={"backup_name": bname},
                    )
                )
            except ToolError:
                raise
            except Exception as err:
                # ``handler.restore`` is domain-specific and can surface
                # HA-side rejections (schema-validation failures, 4xx/5xx
                # responses, WS command errors). Without this catch those
                # propagate as opaque INTERNAL_ERROR with no
                # ``backup_name`` / ``domain`` context — the user is left
                # to read the FastMCP traceback. Funnel through
                # ``exception_to_structured_error`` so the structured
                # response carries enough context to retry.
                exception_to_structured_error(
                    err,
                    context={"backup_name": bname, "action": "restore"},
                    suggestions=[
                        "Verify the entity referenced by the backup still "
                        + "exists; restore re-POSTs to its current registry "
                        + "key",
                        "Compare the captured schema vs current HA — HA "
                        + "minor versions occasionally drop/rename fields",
                        "Inspect the snapshot YAML via "
                        + "ha_manage_backup(scope='edits', action='view', "
                        + "backup_name=...)",
                    ],
                )
                return None  # unreachable: exception_to_structured_error always raises
            return {
                "success": True,
                "data": result,
                "warnings": [
                    "This restore did NOT restart HA. To revert, restore the safety_backup."
                ]
                if result.get("safety_backup")
                else [],
            }

        # action == "delete"
        if backup_name:
            try:
                await asyncio.to_thread(mgr.delete_snapshot, backup_name)
            except FileNotFoundError:
                raise_tool_error(
                    create_error_response(
                        ErrorCode.RESOURCE_NOT_FOUND,
                        f"Backup {backup_name!r} not found",
                        context={"backup_name": backup_name},
                    )
                )
            except ValueError as err:
                raise_tool_error(
                    create_error_response(
                        ErrorCode.VALIDATION_INVALID_PARAMETER,
                        str(err),
                        context={"backup_name": backup_name},
                    )
                )
            return {"success": True, "data": {"deleted": [backup_name]}}
        # Bulk
        if domain is None and entity_id is None and older_than_days is None:
            raise_tool_error(
                create_error_response(
                    ErrorCode.VALIDATION_INVALID_PARAMETER,
                    "edits.delete requires backup_name OR at least one filter "
                    "(domain, entity_id, older_than_days)",
                    suggestions=[
                        "Pass backup_name to delete one auto-backup",
                        "Pass domain/entity_id/older_than_days to bulk-delete (requires at least one)",
                    ],
                )
            )
        bulk = await asyncio.to_thread(
            mgr.delete_bulk,
            domain=domain,
            entity_id=entity_id,
            older_than_days=older_than_days,
        )
        deleted = bulk["deleted"]
        failed = bulk["failed"]
        return {
            "success": True,
            "data": {
                "deleted": deleted,
                "failed": failed,
                "count": len(deleted),
                "failed_count": len(failed),
            },
            "warnings": (
                [f"Failed to delete {len(failed)} backup(s); see server log"]
                if failed
                else []
            ),
        }"
}

{
  "name": "get_polars_version",
  "description": "Get the currently installed Polars version information",
  "inputSchema": {
    "type": "object",
    "properties": {}
  },
  "handler": "def get_polars_version() -> str:
    """
    Get the currently installed Polars version information.

    This tool returns detailed version information about the Polars package
    currently installed in the environment, including the version number,
    installation location, and other metadata.

    Returns:
        str: A JSON-encoded object containing version information:
            {
              "version": "0.20.3",
              "package_name": "polars",
              "location": "/path/to/site-packages",
              "metadata": {
                "author": "...",
                "summary": "...",
                "home_page": "...",
                ...
              }
            }

    Example:
        # Get current Polars version
        get_polars_version()
    """
    try:
        # Get version using importlib.metadata (recommended approach)
        version = importlib.metadata.version("polars")

        # Get additional metadata
        try:
            metadata = importlib.metadata.metadata("polars")
            metadata_dict = dict(metadata)
        except Exception:
            metadata_dict = {}

        # Try to get the module location
        try:
            location = pl.__file__ if hasattr(pl, '__file__') else "Unknown"
            if location and location.endswith("__init__.py"):
                location = location.replace("__init__.py", "")
        except Exception:
            location = "Unknown"

        version_info = {
            "version": version,
            "package_name": "polars",
            "location": location,
            "metadata": metadata_dict
        }

        return json.dumps(version_info, indent=2, default=str)

    except importlib.metadata.PackageNotFoundError:
        # Fallback: try to get version from polars module directly
        try:
            version = getattr(pl, '__version__', 'Unknown')
            version_info = {
                "version": version,
                "package_name": "polars",
                "location": getattr(pl, '__file__', 'Unknown'),
                "metadata": {},
                "note": "Version obtained from module attribute (metadata unavailable)"
            }
            return json.dumps(version_info, indent=2, default=str)

        except Exception as e:
            error_info = {
                "error": "Could not determine Polars version",
                "details": str(e),
                "version": "Unknown",
                "package_name": "polars"
            }
            return json.dumps(error_info, indent=2)"
}

