{
  "name": "add_layer",
  "description": "Add a layer via the bridge (Qt main thread).",
  "inputSchema": {
    "type": "object",
    "properties": {
      "layer_type": {
        "type": "string"
      },
      "path": {
        "type": "string"
      },
      "data": {
        "type": "string"
      },
      "data_var": {
        "type": "string"
      },
      "name": {
        "type": "string"
      },
      "colormap": {
        "type": "string"
      },
      "blending": {
        "type": "string"
      },
      "channel_axis": {
        "type": "string"
      },
      "size": {
        "type": "string"
      },
      "shape_type": {
        "type": "string"
      },
      "edge_color": {
        "type": "string"
      },
      "face_color": {
        "type": "string"
      },
      "edge_width": {
        "type": "string"
      }
    },
    "required": [
      "layer_type"
    ]
  },
  "handler": "async def add_layer(
            layer_type: str,
            path: str | None = None,
            data: list | None = None,
            data_var: str | None = None,
            name: str | None = None,
            colormap: str | None = None,
            blending: str | None = None,
            channel_axis: int | str | None = None,
            size: float | str | None = None,
            shape_type: str | None = None,
            edge_color: str | None = None,
            face_color: str | None = None,
            edge_width: float | str | None = None,
        ):
            """Add a layer via the bridge (Qt main thread)."""
            lt = resolve_layer_type(layer_type)
            if lt is None:
                return {
                    "status": "error",
                    "message": (
                        f"Unknown layer_type '{layer_type}'. "
                        f"Valid types: image, labels, points, shapes, vectors, tracks, surface"
                    ),
                }

            # Validate only one data source
            sources = sum([data_var is not None, data is not None, path is not None])
            if sources > 1:
                return {
                    "status": "error",
                    "message": "Provide only ONE of 'path', 'data', or 'data_var', not multiple.",
                }

            # Resolve data
            resolved: Any | None = None
            if path:
                if lt not in ("image", "labels"):
                    return {
                        "status": "error",
                        "message": f"'path' is only supported for image/labels, not {layer_type}",
                    }
                from pathlib import Path as _Path

                import imageio.v3 as iio

                p = _Path(path).expanduser().resolve(strict=False)
                if not p.exists():
                    return {
                        "status": "error",
                        "message": f"File not found: {p}",
                    }
                try:
                    resolved = iio.imread(str(p))
                except Exception as e:
                    return {
                        "status": "error",
                        "message": f"Failed to read file: {e}",
                    }
            elif data_var:
                if data_var not in self.state.exec_globals:
                    return {
                        "status": "error",
                        "message": f"Variable '{data_var}' not found in execution namespace",
                    }
                resolved = self.state.exec_globals[data_var]
            elif data is not None:
                resolved = data

            if resolved is None:
                if lt == "surface":
                    return {
                        "status": "error",
                        "message": "'data_var' is required for surface layers.",
                    }
                return {
                    "status": "error",
                    "message": "Provide 'path', 'data', or 'data_var'.",
                }

            def _do_add():
                return create_layer_on_viewer(
                    self.viewer,
                    resolved,
                    lt,
                    name=name,
                    colormap=colormap,
                    blending=blending,
                    channel_axis=channel_axis,
                    size=size,
                    shape_type=shape_type,
                    edge_color=edge_color,
                    face_color=face_color,
                    edge_width=edge_width,
                )

            try:
                return self.qt_bridge.run_in_main_thread(_do_add)
            except Exception as e:
                return {
                    "status": "error",
                    "message": f"Failed to add {layer_type} layer: {e}",
                }"
}

