{
  "name": "get_company_posts",
  "description": "Get recent posts from a company's LinkedIn feed.

Args:
    company_name: LinkedIn company name (e.g., "docker", "anthropic", "microsoft")
    ctx: FastMCP context for progress reporting

Returns:
    Dict with url, sections (name -> raw text), and optional references.
    The LLM should parse the raw text to extract individual posts.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "company_name": {
        "type": "string"
      },
      "extractor": {
        "type": "string"
      }
    },
    "required": [
      "company_name"
    ]
  },
  "handler": "async def get_company_posts(
        company_name: str,
        ctx: Context,
        extractor: Any | None = None,
    ) -> dict[str, Any]:
        """
        Get recent posts from a company's LinkedIn feed.

        Args:
            company_name: LinkedIn company name (e.g., "docker", "anthropic", "microsoft")
            ctx: FastMCP context for progress reporting

        Returns:
            Dict with url, sections (name -> raw text), and optional references.
            The LLM should parse the raw text to extract individual posts.
        """
        try:
            extractor = extractor or await get_ready_extractor(
                ctx, tool_name="get_company_posts"
            )
            logger.info("Scraping company posts: %s", company_name)

            await ctx.report_progress(
                progress=0, total=100, message="Starting company posts scrape"
            )

            url = f"https://www.linkedin.com/company/{company_name}/posts/"
            extracted = await extractor.extract_page(url, section_name="posts")

            sections: dict[str, str] = {}
            references: dict[str, list[Reference]] = {}
            section_errors: dict[str, dict[str, Any]] = {}
            if extracted.text and extracted.text != _RATE_LIMITED_MSG:
                sections["posts"] = extracted.text
                if extracted.references:
                    references["posts"] = extracted.references
            elif extracted.error:
                section_errors["posts"] = extracted.error

            await ctx.report_progress(progress=100, total=100, message="Complete")

            result: dict[str, Any] = {
                "url": url,
                "sections": sections,
            }
            if references:
                result["references"] = references
            if section_errors:
                result["section_errors"] = section_errors
            return result

        except AuthenticationError as e:
            try:
                await handle_auth_error(e, ctx)
            except Exception as relogin_exc:
                raise_tool_error(relogin_exc, "get_company_posts")
        except Exception as e:
            raise_tool_error(e, "get_company_posts")"
}

{
  "name": "investigate_code_base",
  "description": "Investigate the code base of the repository in relation to the issue.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "task": {
        "type": "string"
      }
    },
    "required": [
      "task"
    ]
  },
  "handler": "async def investigate_code_base(
    ctx: RunContext[tuple[InvestigateIssue, ReplyToIssue | None]],
    task: Annotated[str, Field(description="A detailed description of the goals of the investigation.")],
) -> InvestigationResult | Failure:  # pyright: ignore[reportUnusedFunction]
    """Investigate the code base of the repository in relation to the issue."""

    with tempfile.TemporaryDirectory() as temp_dir:
        clone: Repo = Repo.clone_from(url=str(ctx.deps[0].repository_git_url()), to_path=temp_dir, depth=1, single_branch=True)
        clone_path: Path = Path(clone.working_dir).resolve()

        # Invoke the Code Agent, passing in the message history from the research agent
        return (
            await code_investigation_agent.run(
                user_prompt=task,
                message_history=ctx.messages,
                deps=clone_path,
            )
        ).output"
}

